(1, 'Corte masculino clássico', '<div class=\"sw-descricao-editorial\" style=\"max-width:100%;width:100%;line-height:1.75;color:#27313e\"><p style=\"font-size:1.05em;margin:0 0 20px\">O corte masculino clássico valoriza a apresentação pessoal com um acabamento planejado para combinar com seu estilo e sua rotina.</p><section style=\"background:#faf8f4;border:1px solid #e9dfce;border-radius:17px;padding:19px 21px;margin:16px 0\"><h3 style=\"margin:0 0 10px;font-size:1.12em;color:#27231e\">✂️ Estilo e resultado</h3><p style=\"margin:0;line-height:1.75\">Antes de começar, o barbeiro avalia comprimento, formato, textura e referências para definir a execução.</p></section><section style=\"background:#faf8f4;border:1px solid #e9dfce;border-radius:17px;padding:19px 21px;margin:16px 0\"><h3 style=\"margin:0 0 10px;font-size:1.12em;color:#27231e\">✓ Como é realizado</h3><p style=\"margin:0;line-height:1.75\">O resultado pode ser ajustado para um visual discreto, moderno ou mais marcante, conforme a preferência.</p></section><section style=\"background:#faf8f4;border:1px solid #e9dfce;border-radius:17px;padding:19px 21px;margin:16px 0\"><h3 style=\"margin:0 0 10px;font-size:1.12em;color:#27231e\">✦ Para quem combina</h3><p style=\"margin:0;line-height:1.75\">Peça orientações de finalização e sobre quando fazer o próximo corte para preservar o formato.</p></section><section style=\"background:#f5eee0;border:1px solid #dfcda9;border-radius:17px;padding:19px 21px;margin:16px 0\"><h3 style=\"margin:0 0 10px;color:#332919\">📅 Cuidados e manutenção</h3><p style=\"margin:0;line-height:1.75\">Entre em contato com a barbearia para confirmar disponibilidade, duração, valores e os detalhes de corte masculino clássico.</p></section></div>', 'corte-masculino-classico.jpg', 'corte-masculino-classico.jpg', 1, '2026-10-20 16:19:07', '2026-10-21 15:14:07', 1, 1, 'Corte masculino clássico', 'Corte masculino clássico: atendimento profissional com técnica, acabamento e atenção aos detalhes.', 'corte-masculino-classico', 'ESTILO E CUIDADO MASCULINO', 'Corte masculino clássico: destaque seu estilo', 'Atendimento profissional para renovar seu visual. Agende seu horário.', 'Saiba mais'),
(2, 'Corte degradê baixo', '<div class=\"sw-descricao-editorial\" style=\"max-width:100%;width:100%;line-height:1.75;color:#27313e\"><p style=\"font-size:1.05em;margin:0 0 20px\">O degradê baixo cria uma transição gradual entre os comprimentos, valorizando o contorno da cabeça e o estilo escolhido.</p><section style=\"background:#faf8f4;border:1px solid #e9dfce;border-radius:17px;padding:19px 21px;margin:16px 0\"><h3 style=\"margin:0 0 10px;font-size:1.12em;color:#27231e\">✂️ Estilo e resultado</h3><p style=\"margin:0;line-height:1.75\">O barbeiro ajusta a altura do degradê, trabalha as laterais com máquina e finaliza o topo conforme o visual combinado.</p></section><section style=\"background:#faf8f4;border:1px solid #e9dfce;border-radius:17px;padding:19px 21px;margin:16px 0\"><h3 style=\"margin:0 0 10px;font-size:1.12em;color:#27231e\">✓ Como é realizado</h3><p style=\"margin:0;line-height:1.75\">É uma opção para quem gosta de laterais bem definidas e deseja adaptar o contraste ao formato do rosto.</p></section><section style=\"background:#faf8f4;border:1px solid #e9dfce;border-radius:17px;padding:19px 21px;margin:16px 0\"><h3 style=\"margin:0 0 10px;font-size:1.12em;color:#27231e\">✦ Para quem combina</h3><p style=\"margin:0;line-height:1.75\">Para conservar a transição marcada, converse sobre a frequência ideal de retoque conforme o crescimento dos fios.</p></section><section style=\"background:#f5eee0;border:1px solid #dfcda9;border-radius:17px;padding:19px 21px;margin:16px 0\"><h3 style=\"margin:0 0 10px;color:#332919\">📅 Cuidados e manutenção</h3><p style=\"margin:0;line-height:1.75\">Entre em contato com a barbearia para confirmar disponibilidade, duração, valores e os detalhes de corte degradê baixo.</p></section></div>', 'corte-degrade-baixo.jpg', 'corte-degrade-baixo.jpg', 1, '2026-10-20 16:19:07', '2026-10-21 15:14:09', 1, 1, 'Corte degradê baixo', 'Corte degradê baixo: atendimento profissional com técnica, acabamento e atenção aos detalhes.', 'corte-deg